import $api from "../http";
import type { AxiosResponse } from "axios/index";
import {ICart} from "../intefaces/commonInterfaces";


export default class CartServices {
    static async getCarts(): Promise<any> {
        return $api.get('/cart');
    }

    static async addCart(doctor_id: number, quantity: number, doctor_type: string): Promise<any> {
        // Отримуємо поточний стан кошика
        const currentCarts = await this.getCarts();

        // Перевіряємо, чи існує вже лікар з таким же doctor_id та doctor_type
        const existingCart = currentCarts.data.find((cart: ICart) => 
            cart.doctor_id === doctor_id && cart.doctor_type === doctor_type
        );

        if (existingCart) {
            // Якщо існує, оновлюємо кількість
            return $api.put(`/cart/${existingCart.id}`, {
                quantity: existingCart.quantity + quantity
            });
        } else {
            // Якщо не існує, додаємо новий запис
            return $api.post(`/cart`, {
                doctor_id,
                quantity,
                doctor_type
            });
        }
    }

    static async deleteCart(item_index: number): Promise<any> {
        return $api.delete(`/cart/${item_index}`);
    }

}
